import data from '../data/zones.json';
import { COLS, ROWS, TILE_COUNT, toIndex } from './coords';

// Zone grid generated by scripts/build-zones.mjs from the zone map image.
// zoneArea holds an area id (1..74) per tile; areaLevel maps area id -> level 1..5 (6 = King's Throne).

export const THRONE_LEVEL = 6;
export const LEVELS = [1, 2, 3, 4, 5, 6] as const;

export const LEVEL_COLORS: Record<number, string> = {
  1: '#E2EFDA',
  2: '#DDEBF7',
  3: '#FCE4D6',
  4: '#F8CBAD',
  5: '#F4B084',
  6: '#D9C3E9',
};

export function levelName(level: number): string {
  return level === THRONE_LEVEL ? "King's Throne" : `Level ${level}`;
}

if (data.cols !== COLS || data.rows !== ROWS) {
  throw new Error(`zones.json is ${data.cols}x${data.rows}, expected ${COLS}x${ROWS}`);
}

export const zoneArea = new Uint8Array(TILE_COUNT);
{
  const rle = data.rle;
  let k = 0;
  for (let i = 0; i < rle.length; i += 2) {
    zoneArea.fill(rle[i], k, k + rle[i + 1]);
    k += rle[i + 1];
  }
}

export const areaLevel = new Uint8Array(256);
for (const a of data.areas) areaLevel[a.id] = a.level;

/** Label position (game coords) of each area, where the level number is printed on the source map. */
export const areaLabels = data.areas.map((a) => ({ level: a.level, x: a.label[0], y: a.label[1] }));

export const zoneLevel = new Uint8Array(TILE_COUNT);
export const tilesPerLevel = new Array<number>(7).fill(0);
for (let i = 0; i < TILE_COUNT; i++) {
  const lvl = areaLevel[zoneArea[i]];
  zoneLevel[i] = lvl;
  tilesPerLevel[lvl]++;
}

export function levelAt(x: number, y: number): number {
  return zoneLevel[toIndex(x, y)];
}
